import {sprite,equipmentArt} from './equipment-art.js';
import {CHEM} from './rates-model.js';
const stroke='stroke="#29415d" stroke-width="2" stroke-linejoin="miter"';
export function art(o,s){
 let image='',extra='',w=80,h=100,top=0;
 if(o.kind==='gasSyringe'){w=270;h=40;top=-24;const p=32+s.collected/100*180;image=`<path d="M0-4H20V-16H220V16H20V4H0Z" fill="#c6e7eb" ${stroke}/><path d="M23-13H217V-9H23" fill="#f2fcf6"/><rect x="24" y="-8" width="${Math.max(0,p-24)}" height="19" fill="#75b8d1" opacity=".3"/><path d="M${p}-14V14M${p} 0H${p+35}M${p+35}-14V14" fill="none" stroke="#45647c" stroke-width="5"/>${Array.from({length:21},(_,i)=>`<path d="M${32+i*9} -16v${i%2?5:9}" stroke="#345371"/>${i%4?'':`<text x="${32+i*9}" y="29" text-anchor="middle" font-size="9">${i*5}</text>`}`).join('')}<text id="gas-reading" x="100" y="-27" font-size="13">${s.collected.toFixed(1)} mL</text>`;return image+'<rect class="select-outline" x="-12" y="-40" width="300" height="85"/>';}
 if(o.kind==='solidBottle'){image=sprite('bottle',-30,0,60,100);extra=`<rect x="-27" y="40" width="54" height="40" fill="#f7efd6"/><text y="56" text-anchor="middle" font-size="9">CaCO₃</text><text y="70" text-anchor="middle" font-size="9">${o.id}</text>`;w=60;}
 else if(o.kind==='vial'){image=sprite('cylinder',-14,0,28,48,[.18,0,.64,.88]);if(o.water>0){const clip='vial-interior-'+o.id;extra=`<defs><clipPath id="${clip}"><path d="M-4 8H4V38Q0 42-4 38Z"/></clipPath></defs><g class="vessel-contents" clip-path="url(#${clip})"><rect x="-4" y="${39-31*Math.min(1,o.water/20)}" width="8" height="${31*Math.min(1,o.water/20)}" fill="#82c1cf" opacity=".5"/></g>`;}w=28;h=48;}
 else if(o.kind==='bung'){image=sprite('stopper',-14,0,28,14)+`<path d="M0 0V-12H20" fill="none" stroke="#689b9c" stroke-width="6"/>`;w=40;h=20;top=-16;}
 else if(o.kind==='clampStand'){image=sprite('stand',-65,1,130,16,[0,.78,1,.22])+sprite('stand',-5,-310,10,310,[.43,0,.12,.8])+`<path d="M0-210H30" stroke="#37506c" stroke-width="8"/>`;return image+'<rect class="select-outline" x="-75" y="-325" width="160" height="350"/>';}
 else if(o.kind==='spatula'){image=sprite('spatula',-9,0,18,70);if(o.chips+o.powder>0)extra=`<ellipse cy="58" rx="6" ry="8" fill="#f4e9cf"/><text x="15" y="55" font-size="10">${(o.chips+o.powder).toFixed(2)} g</text>`;w=18;h=70;}
 else{
  const flask=o.kind==='conical';w=flask?110:78;h=flask?120:96;const html=`<defs><clipPath id="liquid-${o.id}"><path d="${flask?'M-13 0V35L-52 110Q-52 119-43 119H43Q52 119 52 110L13 35V0Z':'M-35 3H35V90H-35Z'}"/></clipPath></defs><g clip-path="url(#liquid-${o.id})">${o.water>0?`<rect x="-${w/2}" y="${h-7-(h-20)*o.water/o.capacity}" width="${w}" height="${(h-20)*o.water/o.capacity}" fill="#99c9d2" opacity=".6"/>`:''}</g><text y="-12" text-anchor="middle" font-size="10">${o.id==='acid'?'HCl · 1.00 M':o.id==='water'?'Water':o.id==='waste'?'Waste':''}</text><rect class="select-outline" x="${-w/2-8}" y="-20" width="${w+16}" height="${h+30}"/>`;
  image=equipmentArt(o,html,'reaction-rates',s);extra='';
 }
 return image+extra+`<rect class="select-outline" x="${-w/2-8}" y="${top-8}" width="${w+16}" height="${h-top+20}"/>`;
}
export function graph(trials,current){const series=trials.filter(t=>t.id!==current.trialId).map((t,i)=>({...t,color:['#347a9b','#b46c43','#68834e','#856a9e'][i%4]}));if(current.records.length)series.push({id:current.trialId,records:current.records,charge:current.charge,color:['#347a9b','#b46c43','#68834e','#856a9e'][series.length%4]});const maxT=Math.max(10,Math.ceil(Math.max(0,...series.flatMap(t=>t.records.map(r=>r.time)))/10)*10),maxV=Math.max(50,Math.ceil(Math.max(0,...series.flatMap(t=>t.records.map(r=>r.volume)))/10)*10);return `<svg class="rates-graph" viewBox="0 0 660 300" role="img" aria-label="Collected carbon dioxide volume in millilitres against stopwatch time in seconds"><rect x="55" y="15" width="580" height="235" fill="#faf9f0"/>${Array.from({length:6},(_,i)=>`<path d="M55 ${250-i*47}H635M${55+i*116} 15V250" stroke="#d5dfd5"/><text x="47" y="${254-i*47}" text-anchor="end" font-size="11">${(maxV*i/5).toFixed(0)}</text><text x="${55+i*116}" y="267" text-anchor="middle" font-size="11">${(maxT*i/5).toFixed(0)}</text>`).join('')}<path d="M55 15V250H635" fill="none" stroke="#365568"/><text x="345" y="294" text-anchor="middle" font-size="12">Time / s</text><text transform="translate(14 145) rotate(-90)" text-anchor="middle" font-size="12">CO₂ collected / mL</text>${series.map(t=>`<polyline data-trial="${t.id}" fill="none" stroke="${t.color}" stroke-width="2.5" points="${t.records.map(r=>`${55+580*r.time/maxT},${250-235*r.volume/maxV}`).join(' ')}"/>${t.records.map(r=>`<circle cx="${55+580*r.time/maxT}" cy="${250-235*r.volume/maxV}" r="3" fill="${t.color}"/>`).join('')}`).join('')}</svg><div class="rates-legend">${series.map(t=>`<span style="color:${t.color}">● Trial ${t.id}${t.charge?' · '+(t.charge.chips&&t.charge.powder?'mixed solids':t.charge.powder?'powder':'chips'):''}</span>`).join('')}</div>`;}
